// K-means clustering: batch Lloyd/Forgy, online MacQueen, and point-transfer Hartigan-Wong.
import { sampleInt } from "../random/sample.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const KMEANS_KEYS = ["algorithm", "iterMax", "nstart"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** @category Multivariate analysis */
export interface KmeansOptions {
  /** Clustering algorithm; a unique prefix is accepted. */
  algorithm?: "Hartigan-Wong" | "Lloyd" | "Forgy" | "MacQueen" | string;
  /** Maximum number of algorithm iterations (R's iter.max). */
  iterMax?: number;
  /** Number of random initial starts when centers is a count. */
  nstart?: number;
}

/** @category Multivariate analysis */
export interface KmeansInputTable {
  /** Optional observation names, one per row. */
  rows: string[] | null;
  /** Optional variable names, one per column. */
  cols: string[] | null;
  /** Numeric observations arranged by row. */
  values: readonly (readonly number[])[];
}

/** @category Multivariate analysis */
export interface KmeansTable {
  /** Cluster labels corresponding to the rows of the center matrix. */
  rows: string[];
  /** Variable names, or null when the input had no column names. */
  cols: string[] | null;
  /** Cluster centers arranged by row. */
  values: number[][];
}

/** @category Multivariate analysis */
export interface KmeansFit {
  /** 1-based cluster assignment for each observation. */
  cluster: number[];
  /** Observation names, present when the input supplied row names. */
  names?: string[];
  /** Matrix of final cluster centers. */
  centers: KmeansTable;
  /** Total sum of squares around the overall sample mean. */
  totss: number;
  /** Within-cluster sums of squares, one per cluster. */
  withinss: number[];
  /** Sum of all within-cluster sums of squares. */
  totWithinss: number;
  /** Between-cluster sum of squares (totss minus totWithinss). */
  betweenss: number;
  /** Number of observations assigned to each cluster. */
  size: number[];
  /** Number of iterations reported by the selected algorithm. */
  iter: number;
  /** Hartigan-Wong fault code, or null for algorithms without one. */
  ifault: number | null;
  /** Warnings produced during clustering. */
  warnings: string[];
}

interface InputData { rows: number[][]; rowNames: string[] | null; colNames: string[] | null; }

function readData(x: readonly unknown[] | readonly (readonly unknown[])[] | Record<string, ArrayLike<unknown>> | KmeansInputTable): InputData {
  if (Array.isArray(x)) {
    if (x.length === 0) throw new RangeError("x must be a non-empty numeric matrix");
    if (!Array.isArray(x[0])) return { rows: x.map((v) => [Number(v)]), rowNames: null, colNames: null };
    const raw = x as readonly (readonly unknown[])[];
    const p = raw[0]!.length;
    if (p === 0 || raw.some((r) => r.length !== p)) throw new RangeError("x must be a non-empty matrix with equal row lengths");
    return { rows: raw.map((r) => r.map(Number)), rowNames: null, colNames: null };
  }
  if (typeof x === "object" && x !== null) {
    const table = x as { values?: readonly (readonly unknown[])[]; rows?: string[] | null; cols?: string[] | null };
    if (Array.isArray(table.values)) {
      const raw = table.values;
      const p = raw[0]?.length ?? 0;
      if (p === 0 || raw.some((r) => r.length !== p)) throw new RangeError("x must be a non-empty matrix with equal row lengths");
      return { rows: raw.map((r) => r.map(Number)), rowNames: table.rows ?? null, colNames: table.cols ?? null };
    }
    const cols = Object.entries(x as Record<string, ArrayLike<unknown>>);
    if (cols.length === 0) throw new RangeError("x must have at least one column");
    const n = cols[0]![1].length;
    if (cols.some(([, v]) => v.length !== n)) throw new RangeError("columns must have equal lengths");
    return { rows: Array.from({ length: n }, (_, i) => cols.map(([, v]) => Number(v[i]))), rowNames: null,
      colNames: cols.map(([name]) => name) };
  }
  throw new TypeError("x must be a numeric vector, matrix, or data frame");
}

function sameRow(a: readonly number[], b: readonly number[]): boolean {
  return a.length === b.length && a.every((v, i) => Object.is(v, b[i]));
}
function squared(a: readonly number[], b: readonly number[]): number {
  let s = 0;
  for (let j = 0; j < a.length; j++) { const d = a[j]! - b[j]!; s += d * d; }
  return s;
}
function nearest(row: readonly number[], centers: readonly (readonly number[])[]): number {
  let best = 0, value = squared(row, centers[0]!);
  for (let j = 1; j < centers.length; j++) {
    const d = squared(row, centers[j]!);
    if (d < value) { best = j; value = d; }
  }
  return best;
}
function means(rows: readonly (readonly number[])[], cluster: readonly number[], k: number, p: number): { centers: number[][]; size: number[] } {
  const centers = Array.from({ length: k }, () => new Array<number>(p).fill(0));
  const size = new Array<number>(k).fill(0);
  for (let i = 0; i < rows.length; i++) {
    const g = cluster[i]!;
    size[g] = size[g]! + 1;
    for (let j = 0; j < p; j++) centers[g]![j] = centers[g]![j]! + rows[i]![j]!;
  }
  for (let g = 0; g < k; g++) if (size[g]! > 0) {
    for (let j = 0; j < p; j++) centers[g]![j] = centers[g]![j]! / size[g]!;
  }
  return { centers, size };
}
function totalSS(rows: readonly (readonly number[])[], p: number): number {
  const center = new Array<number>(p).fill(0);
  for (const row of rows) for (let j = 0; j < p; j++) center[j] = center[j]! + row[j]!;
  for (let j = 0; j < p; j++) center[j] = center[j]! / rows.length;
  let sum = 0;
  for (const row of rows) sum += squared(row, center);
  return sum;
}
function fitStats(rows: number[][], cluster: number[], k: number, colNames: string[] | null,
  rowNames: string[] | null, iter: number, ifault: number | null, warnings: string[]): KmeansFit {
  const p = rows[0]!.length;
  const { centers, size } = means(rows, cluster, k, p);
  // R reports the center of an empty cluster as NaN (the mean of no rows; kmeans_empty_Lloyd)
  for (let g = 0; g < k; g++) if (size[g] === 0) centers[g] = new Array<number>(p).fill(NaN);
  const withinss = new Array<number>(k).fill(0);
  for (let i = 0; i < rows.length; i++) withinss[cluster[i]!]! += squared(rows[i]!, centers[cluster[i]!]!);
  const totss = totalSS(rows, p);
  const totWithinss = withinss.reduce((a, b) => a + b, 0);
  const out: KmeansFit = { cluster: cluster.map((v) => v + 1), centers: {
    rows: Array.from({ length: k }, (_, i) => String(i + 1)), cols: colNames, values: centers,
  }, totss, withinss, totWithinss, betweenss: totss - totWithinss, size, iter, ifault, warnings };
  if (rowNames !== null) out.names = [...rowNames];
  return out;
}
function lloyd(rows: number[][], initial: number[][], iterMax: number): { cluster: number[]; iter: number; converged: boolean } {
  // Batch updates: assign every row to its nearest center, stop when no assignment changed, else move each nonempty
  // center to its mean. R counts the assignment passes (the last one confirms convergence) and reports
  // iter.max + 1 when it stops at the limit (kmeans_iter_Lloyd_1..5, kmeans_vector_Lloyd)
  const k = initial.length;
  const centers = initial.map((r) => [...r]);
  let cluster: number[] = new Array<number>(rows.length).fill(-1);
  for (let iter = 1; iter <= iterMax; iter++) {
    const next = rows.map((row) => nearest(row, centers));
    const changed = next.some((v, i) => v !== cluster[i]);
    cluster = next;
    if (!changed) return { cluster, iter, converged: true };
    const stats = means(rows, cluster, k, rows[0]!.length);
    for (let g = 0; g < k; g++) if (stats.size[g]! > 0) centers[g] = stats.centers[g]!;
  }
  return { cluster, iter: iterMax + 1, converged: false };
}
function macqueen(rows: number[][], initial: number[][], iterMax: number): { cluster: number[]; iter: number; converged: boolean } {
  const k = initial.length, p = rows[0]!.length;
  let cluster = rows.map((row) => nearest(row, initial));
  const { centers, size } = means(rows, cluster, k, p);
  // an empty cluster keeps its initial center (R: kmeans_empty_MacQueen), not the mean of no rows
  for (let g = 0; g < k; g++) if (size[g] === 0) centers[g] = [...initial[g]!];
  let converged = false, iter = 0;
  for (let pass = 0; pass < iterMax; pass++) {
    let moved = false;
    // MacQueen's sequential update: each transfer changes the two means and
    // their counts immediately, so subsequent observations see the new fit.
    for (let i = 0; i < rows.length; i++) {
      const from = cluster[i]!;
      if (size[from]! <= 1) continue;
      const to = nearest(rows[i]!, centers);
      if (to === from) continue;
      const row = rows[i]!;
      const oldN = size[from]!, newN = size[to]!;
      for (let j = 0; j < p; j++) {
        centers[from]![j] = (oldN * centers[from]![j]! - row[j]!) / (oldN - 1);
        centers[to]![j] = (newN * centers[to]![j]! + row[j]!) / (newN + 1);
      }
      size[from] = oldN - 1;
      size[to] = newN + 1;
      cluster[i] = to;
      moved = true;
    }
    iter = pass + 1;
    if (!moved) { converged = true; break; }
  }
  return { cluster, iter: converged ? iter : iterMax + 1, converged };
}
function hartiganWong(rows: number[][], initial: number[][], iterMax: number): { cluster: number[]; iter: number; converged: boolean } {
  // Hartigan & Wong (1979), from the paper's description (not from AS 136's code): an optimal-transfer stage over a
  // live set of clusters, then a quick-transfer stage between each point's closest and second-closest clusters,
  // repeated until an optimal-transfer pass moves nothing. iter counts the optimal-transfer passes; R reports
  // iter.max + 1 at the limit (kmeans_iter_Hartigan-Wong_1..5)
  const n = rows.length, k = initial.length, p = rows[0]!.length;
  const ic1 = new Array<number>(n), ic2 = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    let b1 = 0, b2 = 1, d1 = squared(rows[i]!, initial[0]!), d2 = squared(rows[i]!, initial[1]!);
    if (d2 < d1) { [b1, b2, d1, d2] = [1, 0, d2, d1]; }
    for (let g = 2; g < k; g++) {
      const d = squared(rows[i]!, initial[g]!);
      if (d < d1) { b2 = b1; d2 = d1; b1 = g; d1 = d; } else if (d < d2) { b2 = g; d2 = d; }
    }
    ic1[i] = b1; ic2[i] = b2;
  }
  const { centers, size } = means(rows, ic1, k, p);
  if (size.some((v) => v === 0)) throw new RangeError("empty cluster: try a better set of initial centers");
  const move = (i: number, from: number, to: number): void => {
    const row = rows[i]!, oldN = size[from]!, newN = size[to]!;
    for (let j = 0; j < p; j++) {
      centers[from]![j] = (oldN * centers[from]![j]! - row[j]!) / (oldN - 1);
      centers[to]![j] = (newN * centers[to]![j]! + row[j]!) / (newN + 1);
    }
    size[from] = oldN - 1; size[to] = newN + 1; ic1[i] = to; ic2[i] = from;
  };
  const removeCost = (i: number, g: number): number => size[g]! / (size[g]! - 1) * squared(rows[i]!, centers[g]!);
  const addCost = (i: number, g: number): number => size[g]! / (size[g]! + 1) * squared(rows[i]!, centers[g]!);
  // live set: cluster g is live at optimal-transfer step t when it was updated within the last n steps
  const updated = new Array<number>(k).fill(0);
  let t = 0;
  for (let iter = 1; iter <= iterMax; iter++) {
    let moved = false;
    for (let i = 0; i < n; i++) {
      t++;
      const l1 = ic1[i]!;
      if (size[l1]! === 1) continue;
      const live = (g: number): boolean => updated[g]! >= t - n;
      const l1Live = live(l1);
      let best = ic2[i]!, bestCost = addCost(i, best);
      for (let g = 0; g < k; g++) {
        if (g === l1 || g === ic2[i] || !(l1Live || live(g))) continue;
        const c = addCost(i, g);
        if (c < bestCost) { best = g; bestCost = c; }
      }
      if (bestCost < removeCost(i, l1)) { move(i, l1, best); updated[l1] = t; updated[best] = t; moved = true; }
      else ic2[i] = best;
    }
    if (!moved) return { cluster: ic1, iter, converged: true };
    // quick transfer: until n consecutive steps move nothing
    let quiet = 0;
    for (let i = 0; quiet < n; i = (i + 1) % n) {
      const l1 = ic1[i]!, l2 = ic2[i]!;
      if (size[l1]! > 1 && addCost(i, l2) < removeCost(i, l1)) { move(i, l1, l2); updated[l1] = t; updated[l2] = t; quiet = 0; }
      else quiet++;
    }
    // with two clusters the quick-transfer stage has tried every transfer: no need to return to the optimal-transfer
    // stage (Hartigan & Wong 1979; kmeans_equal_best_seed_*)
    if (k === 2) return { cluster: ic1, iter, converged: true };
  }
  return { cluster: ic1, iter: iterMax + 1, converged: false };
}

/**
 * K-means clustering by the Hartigan-Wong, Lloyd, Forgy or MacQueen algorithm.
 * Equivalent to R's `kmeans()`.
 * @category Multivariate analysis
 */
export function kmeans(
  x: readonly unknown[] | readonly (readonly unknown[])[] | Record<string, ArrayLike<unknown>> | KmeansInputTable,
  centersInput: number | readonly number[] | readonly (readonly number[])[],
  options: KmeansOptions = {},
): KmeansFit {
  checkOptions(options, KMEANS_KEYS, "kmeans"); // generated: option-keys.mjs
  const data = readData(x);
  const rows = data.rows, n = rows.length, p = rows[0]?.length ?? 0;
  if (n < 1 || p < 1 || rows.some((r) => r.length !== p)) throw new RangeError("x must be a non-empty matrix");
  if (rows.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("NA/NaN/Inf in foreign function call (arg 1)");
  const algorithms = ["Hartigan-Wong", "Lloyd", "Forgy", "MacQueen"];
  const requested = options.algorithm ?? "Hartigan-Wong";
  const matches = algorithms.filter((v) => v.startsWith(requested));
  if (matches.length !== 1) throw new RangeError("invalid algorithm");
  const algorithm = matches[0]!;
  const iterMax = options.iterMax ?? 10;
  if (!Number.isFinite(iterMax) || iterMax < 1) throw new RangeError("'iter.max' must be positive");
  const maxIterations = Math.trunc(iterMax);
  const nstart = Math.max(1, Math.trunc(options.nstart ?? 1));
  let initialSets: number[][][] = [];
  if (typeof centersInput === "number") {
    const k = Math.trunc(centersInput);
    if (k < 1 || k > n) throw new RangeError("centers must be between 1 and nrow(x)");
    const distinct = new Set(rows.map((r) => JSON.stringify(r))).size;
    if (k > distinct) throw new RangeError("more cluster centers than distinct data points.");
    // R's first start (kmeans_dup_start_seed_1..12, checked by the random state afterwards): k rows by
    // sample.int(nrow, k); when those rows are not distinct, one draw of k rows from the distinct rows (in order of
    // first appearance)
    const unique: number[][] = [];
    const seen = new Set<string>();
    for (const r of rows) { const key = JSON.stringify(r); if (!seen.has(key)) { seen.add(key); unique.push(r); } }
    const draw = (): number[][] => {
      let chosen = sampleInt(n, { size: k }).map((i) => [...rows[i]!]);
      if (new Set(chosen.map((r) => JSON.stringify(r))).size !== k) {
        chosen = sampleInt(unique.length, { size: k }).map((i) => [...unique[i]!]);
      }
      return chosen;
    };
    // with nstart >= 2 every start draws k of the distinct rows (kmeans_equal_best_dup_seed_1..8 and
    // experiments/cluster110-nstart-rng.json: the random state after nstart = 2..5 for 8 seeds)
    if (nstart === 1) initialSets.push(draw());
    else for (let start = 0; start < nstart; start++) {
      initialSets.push(sampleInt(unique.length, { size: k }).map((i) => [...unique[i]!]));
    }
  } else {
    const initial = centersInput.length > 0 && typeof centersInput[0] === "number"
      ? (centersInput as readonly number[]).map((v) => [Number(v)])
      : (centersInput as readonly (readonly number[])[]).map((r) => Array.from(r, Number));
    if (initial.length < 1 || initial.some((r) => r.length !== p)) throw new RangeError("must have same number of columns in 'x' and 'centers'");
    if (initial.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("initial centers must be finite");
    for (let i = 0; i < initial.length; i++) for (let j = 0; j < i; j++) {
      if (sameRow(initial[i]!, initial[j]!)) throw new RangeError("initial centers are not distinct");
    }
    initialSets = [initial];
  }
  const k = initialSets[0]!.length;
  if (algorithm === "Hartigan-Wong" && k === n) throw new RangeError("number of cluster centres must lie between 1 and nrow(x)");

  // Normalize only extreme magnitudes before computing squared distances. This keeps assignments and
  // center updates scale-equivariant when squaring would overflow or underflow; ordinary inputs keep
  // the exact arithmetic path used by the R fixtures. Starts are selected above from the original rows,
  // so this transformation does not alter the random stream or duplicate-row decisions.
  let magnitude = 0;
  for (const row of rows) for (const value of row) magnitude = Math.max(magnitude, Math.abs(value));
  for (const initial of initialSets) for (const row of initial) for (const value of row) magnitude = Math.max(magnitude, Math.abs(value));
  const rescale = magnitude > 2 ** 450 || (magnitude > 0 && magnitude < 2 ** -450);
  const workRows = rescale ? rows.map((row) => row.map((value) => value / magnitude)) : rows;
  const workInitialSets = rescale ? initialSets.map((set) => set.map((row) => row.map((value) => value / magnitude))) : initialSets;
  let best: KmeansFit | null = null;
  let bestW = Infinity;
  let anyNotConverged = false;
  for (const initial of workInitialSets) {
    // One cluster: R does no iteration (iter 1, ifault NULL for every algorithm; kmeans_k1_*)
    const result = k === 1 ? { cluster: new Array<number>(n).fill(0), iter: 1, converged: true }
      : algorithm === "Hartigan-Wong" ? hartiganWong(workRows, initial, maxIterations)
      : algorithm === "MacQueen" ? macqueen(workRows, initial, maxIterations) : lloyd(workRows, initial, maxIterations);
    const warnings: string[] = [];
    const stats = means(workRows, result.cluster, k, p);
    if (stats.size.some((v) => v === 0)) {
      if (algorithm === "Hartigan-Wong") throw new RangeError("empty cluster: try a better set of initial centers");
      warnings.push("empty cluster: try a better set of initial centers", "empty cluster: try a better set of initial centers");
    }
    if (!result.converged) anyNotConverged = true;
    const fit = fitStats(workRows, result.cluster, k, data.colNames, data.rowNames, result.iter,
      algorithm === "Hartigan-Wong" && k > 1 ? (result.converged ? 0 : 2) : (result.converged ? null : 2), warnings);
    if (fit.totWithinss < bestW) { best = fit; bestW = fit.totWithinss; }
  }
  // Return centers and sums of squares on the caller's original scale.
  if (rescale) {
    const restoreSquare = (value: number): number => value === 0 ? 0 : (value * magnitude) * magnitude;
    best!.centers.values = best!.centers.values.map((row) => row.map((value) => value * magnitude));
    best!.totss = restoreSquare(best!.totss);
    best!.withinss = best!.withinss.map(restoreSquare);
    best!.totWithinss = restoreSquare(best!.totWithinss);
    best!.betweenss = restoreSquare(best!.betweenss);
  }
  // R warns once when any start stopped at iter.max, even when the kept start converged (kmeans_seed_nstart_lloyd)
  if (anyNotConverged) best!.warnings.push(`did not converge in ${maxIterations} ${maxIterations === 1 ? "iteration" : "iterations"}`);
  return best!;
}
